// Entry point for the agent host utility process.
// Sets up IPC, logging, and registers agent providers (Copilot).
// When VSCODE_AGENT_HOST_PORT or VSCODE_AGENT_HOST_SOCKET_PATH env vars
// are set, also starts a WebSocket server for external clients.

startAgentHost();

function startAgentHost(): void {
	const disposables = new DisposableStore();
	const logService = new LogService(new LoggerService());
	const sideEffects: IProtocolSideEffectHandler[] = [];
	const wsServer = new WebSocketProtocolServer();
	const host = process.env.VSCODE_AGENT_HOST_PORT ? 'localhost' : '127.0.0.1';
	const port = parseInt(process.env.VSCODE_AGENT_HOST_PORT || '3000', 10);
	const socketPath = process.env.VSCODE_AGENT_HOST_SOCKET_PATH;
	const onConnectionCountChanged = (count: number) => {
		logService.info(`[AgentHost] Connection count changed to ${count}`);
	};
	const agentService = new AgentService(new NativeEnvironmentService(), new FileService(new DiskFileSystemProvider()), new SessionDataService(), logService);
	const protocolHandler = disposables.add(new ProtocolServerHandler(agentService.stateManager, wsServer, sideEffects, logService));
	protocolHandler.onDidChangeConnectionCount(onConnectionCountChanged);
	const listenTarget = socketPath ?? `${host}:${port}`;
	logService.info(`[AgentHost] WebSocket server listening on ${listenTarget}`);
	console.log(`Agent host server listening on ${listenTarget}`);
}

